// Template abstracto de un Esquema Voraz en Java
public abstract class EsquemaGreedy<Candidato, Solucion> {
    public Solucion ejecutarGreedy(java.util.List<Candidato> candidatos) {
        Solucion sol = inicializarSolucion();
        // Ordenamiento o cola de prioridad según el criterio de selección
        ordenarCandidatos(candidatos);
        int i = 0;
        while (i < candidatos.size() && !esSolucion(sol)) {
            Candidato x = candidatos.get(i);
            if (esFactible(sol, x)) {
                incorporar(sol, x);
            }
            i++;
        }
        if (esSolucion(sol)) {
            return sol;
        } else {
            throw new IllegalStateException("No existe solución factible para esta instancia.");
        }
    }
    protected abstract Solucion inicializarSolucion();
    protected abstract void ordenarCandidatos(java.util.List<Candidato> c);
    protected abstract boolean esFactible(Solucion s, Candidato x);
    protected abstract void incorporar(Solucion s, Candidato x);
    protected abstract boolean esSolucion(Solucion s);
}

public static ConjuntoRepTDA<Integer> cambio(VectorTDA<Integer> monedas, int valor) throws Exception {
    // monedas contiene las denominaciones ordenadas de mayor a menor: [100, 50, 25, 10, 5, 1]
    ConjuntoRepTDA<Integer> resultado = new ConjuntoRep<Integer>();
    resultado.InicializarConjunto();
    int suma = 0;
    int i = 0;
    while (suma < valor && i < monedas.longitud()) {
        if (suma + monedas.recuperarElemento(i) <= valor) {
            resultado.Agregar(monedas.recuperarElemento(i));
            suma += monedas.recuperarElemento(i);
        } else {
            i++;
        }
    }
    if (suma == valor) {
        return resultado;
    } else {
        throw new Exception("No es posible dar cambio exacto con las monedas disponibles.");
    }
}

public static VectorTDA<Double> mochila(VectorTDA<Integer> o_valores, VectorTDA<Integer> o_pesos, int o_cantidad, int m_peso) throws Exception {
    VectorTDA<Double> resultado = new Vector<Double>();
    resultado.inicializarVector(o_cantidad);
    for (int i = 0; i < o_cantidad; i++) {
        resultado.agregarElemento(i, 0.0);
    }
    // Se utiliza ColaPrioridadTDA para simular el ordenamiento por ratio valor/peso
    // Prioridad: ratio escalado como entero grande (o Double si soporta genéricos)
    ColaPrioridadTDA<Integer> cola = new ColaPrioridad<Integer>();
    cola.InicializarCola();
    for (int i = 0; i < o_cantidad; i++) {
        int ratioPrioridad = (int) (((double) o_valores.recuperarElemento(i) / o_pesos.recuperarElemento(i)) * 10000);
        cola.AgregarElemento(i, ratioPrioridad);
    }
    double suma = 0.0;
    while (suma < m_peso && !cola.ColaVacia()) {
        int obj = cola.RecuperarMaxElemento();
        int pesoObj = o_pesos.recuperarElemento(obj);
        double fraccion = Math.min(1.0, (double) (m_peso - suma) / pesoObj);
        resultado.agregarElemento(obj, fraccion);
        suma += fraccion * pesoObj;
        cola.EliminarMaxPrioridad();
    }
    return resultado;
}

public class HuffmanNode implements Comparable<HuffmanNode> {
    char simbolo;
    int frecuencia;
    HuffmanNode izq, der;
    public HuffmanNode(char simbolo, int frecuencia) {
        this.simbolo = simbolo;
        this.frecuencia = frecuencia;
    }
    public HuffmanNode(int frecuencia, HuffmanNode izq, HuffmanNode der) {
        this.simbolo = '\0';
        this.frecuencia = frecuencia;
        this.izq = izq;
        this.der = der;
    }
    public boolean esHoja() {
        return this.izq == null && this.der == null;
    }
    @Override
    public int compareTo(HuffmanNode o) {
        return Integer.compare(this.frecuencia, o.frecuencia);
    }
}

public class HuffmanAlgorithm {
    public static HuffmanNode construirArbol(char[] simbolos, int[] frecuencias) {
        java.util.PriorityQueue<HuffmanNode> pq = new java.util.PriorityQueue<HuffmanNode>();
        for (int i = 0; i < simbolos.length; i++) {
            pq.add(new HuffmanNode(simbolos[i], frecuencias[i]));
        }
        while (pq.size() > 1) {
            HuffmanNode x = pq.poll();
            HuffmanNode y = pq.poll();
            HuffmanNode padre = new HuffmanNode(x.frecuencia + y.frecuencia, x, y);
            pq.add(padre);
        }
        return pq.peek();
    }
}

public class GaleShapley {
    public static int[] emparejar(int[][] prefHombres, int[][] prefMujeres, int n) {
        // prefHombres[m][k] indica la k-ésima mujer preferida por m
        // prefMujeres[w][m] indica el orden de ranking del hombre m para la mujer w
        int[] esposoDe = new int[n];
        int[] proximaPropuesta = new int[n];
        boolean[] hombreLibre = new boolean[n];
        java.util.Arrays.fill(esposoDe, -1);
        java.util.Arrays.fill(hombreLibre, true);
        int libresCount = n;

        // Matriz inversa para consulta de preferencia de mujeres en O(1)
        int[][] rankingMujeres = new int[n][n];
        for (int w = 0; w < n; w++) {
            for (int rank = 0; rank < n; rank++) {
                int m = prefMujeres[w][rank];
                rankingMujeres[w][m] = rank;
            }
        }

        while (libresCount > 0) {
            int m;
            for (m = 0; m < n; m++) {
                if (hombreLibre[m]) break;
            }
            int w = prefHombres[m][proximaPropuesta[m]++];
            if (esposoDe[w] == -1) {
                esposoDe[w] = m;
                hombreLibre[m] = false;
                libresCount--;
            } else {
                int actual = esposoDe[w];
                if (rankingMujeres[w][m] < rankingMujeres[w][actual]) {
                    esposoDe[w] = m;
                    hombreLibre[m] = false;
                    hombreLibre[actual] = true;
                }
            }
        }
        return esposoDe; // Retorna para cada mujer w, su esposo m
    }
}

public static int planificar(VectorTDA<Integer> ganancias, VectorTDA<Integer> tiempos, int cantidad, VectorTDA<Integer> resultado) throws Exception {
    ColaPrioridadTDA<Integer> cola = new ColaPrioridad<Integer>();
    cola.InicializarCola();
    for (int i = 0; i < cantidad; i++) {
        cola.AgregarElemento(i, ganancias.recuperarElemento(i));
    }
    int cantidad_secuencia = 0;
    if (!cola.ColaVacia()) {
        resultado.agregarElemento(0, cola.RecuperarMaxElemento());
        cola.EliminarMaxPrioridad();
        cantidad_secuencia = 1;
    }
    while (!cola.ColaVacia()) {
        int candidata = cola.RecuperarMaxElemento();
        int plazoCand = tiempos.recuperarElemento(candidata);
        int j = cantidad_secuencia - 1;
        while (j >= 0 && tiempos.recuperarElemento(resultado.recuperarElemento(j)) > Math.max(plazoCand, j + 1)) {
            j--;
        }
        if (plazoCand > j + 1) {
            // Desplazar elementos hacia la derecha para hacer lugar a la nueva tarea
            for (int m = cantidad_secuencia - 1; m > j; m--) {
                resultado.agregarElemento(m + 1, resultado.recuperarElemento(m));
            }
            resultado.agregarElemento(j + 1, candidata);
            cantidad_secuencia++;
        }
        cola.EliminarMaxPrioridad();
    }
    return cantidad_secuencia;
}

public static VectorTDA<Integer> minimizarEspera(VectorTDA<Integer> tareas, int cantidad) throws Exception {
    VectorTDA<Integer> resultado = new Vector<Integer>();
    resultado.inicializarVector(cantidad);
    ColaPrioridadTDA<Integer> cola = new ColaPrioridad<Integer>();
    cola.InicializarCola();
    // Se cargan las tareas en la cola de prioridad mínima
    for (int i = 0; i < cantidad; i++) {
        cola.AgregarElemento(i, tareas.recuperarElemento(i));
    }
    int i = 0;
    while (!cola.ColaVacia()) {
        resultado.agregarElemento(i, cola.RecuperarMinElemento());
        cola.EliminarMinPrioridad();
        i++;
    }
    return resultado;
}

// Verificación de la condición euleriana sobre GrafoTDA
public static String verificarCondicionEuleriana(GrafoTDA<Integer> g) throws Exception {
    ConjuntoTDA<Integer> verts = g.Vertices();
    int impares = 0;
    while (!verts.conjuntoVacio()) {
        int v = verts.elegir();
        verts.sacar(v);
        ConjuntoTDA<Integer> ady = g.Adyacentes(v);
        int grado = 0;
        while (!ady.conjuntoVacio()) {
            int w = ady.elegir();
            ady.sacar(w);
            grado++;
        }
        if (grado % 2 != 0) {
            impares++;
        }
    }
    if (impares == 0) return "Ciclo Euleriano";
    if (impares == 2) return "Camino Euleriano";
    return "No es Euleriano";
}

public static GrafoDirTDA<Integer> dijkstra(GrafoDirTDA<Integer> g, int origen) throws Exception {
    // Implementación sobre los TDA de cátedra devolviendo el grafo con costos mínimos desde el origen
    GrafoDirTDA<Integer> distanciasMinimas = new GrafoDir<Integer>();
    distanciasMinimas.InicializarGrafo();
    distanciasMinimas.AgregarVertice(origen);

    ConjuntoTDA<Integer> vertices = g.Vertices();
    vertices.sacar(origen);
    while (!vertices.conjuntoVacio()) {
        int v = vertices.elegir();
        vertices.sacar(v);
        distanciasMinimas.AgregarVertice(v);
        if (g.ExisteArista(origen, v)) {
            distanciasMinimas.AgregarArista(origen, v, g.PesoArista(origen, v));
        }
    }

    ConjuntoTDA<Integer> pendientes = g.Vertices();
    pendientes.sacar(origen);
    ConjuntoTDA<Integer> aux_pendientes = new Conjunto<Integer>();
    aux_pendientes.inicializarConjunto();

    while (!pendientes.conjuntoVacio()) {
        int mejor_distancia = 0;
        int mejor_vertice = 0;
        boolean encontrado = false;

        // Búsqueda del vértice no visitado con menor costo desde el origen
        while (!pendientes.conjuntoVacio()) {
            int aux_vertice = pendientes.elegir();
            pendientes.sacar(aux_vertice);
            aux_pendientes.agregar(aux_vertice);
            if (distanciasMinimas.ExisteArista(origen, aux_vertice)) {
                int d = distanciasMinimas.PesoArista(origen, aux_vertice);
                if (!encontrado || d < mejor_distancia) {
                    mejor_distancia = d;
                    mejor_vertice = aux_vertice;
                    encontrado = true;
                }
            }
        }

        if (!encontrado) break; // Nodos restantes son inalcanzables

        int vertice = mejor_vertice;
        aux_pendientes.sacar(vertice);

        // Relajación de aristas hacia los pendientes restantes
        while (!aux_pendientes.conjuntoVacio()) {
            int aux_vertice = aux_pendientes.elegir();
            aux_pendientes.sacar(aux_vertice);
            pendientes.agregar(aux_vertice);

            if (g.ExisteArista(vertice, aux_vertice)) {
                int nuevoCosto = distanciasMinimas.PesoArista(origen, vertice) + g.PesoArista(vertice, aux_vertice);
                if (!distanciasMinimas.ExisteArista(origen, aux_vertice)) {
                    distanciasMinimas.AgregarArista(origen, aux_vertice, nuevoCosto);
                } else if (distanciasMinimas.PesoArista(origen, aux_vertice) > nuevoCosto) {
                    distanciasMinimas.AgregarArista(origen, aux_vertice, nuevoCosto);
                }
            }
        }
    }
    return distanciasMinimas;
}

public static GrafoTDA<Integer> prim(GrafoTDA<Integer> g) throws Exception {
    GrafoTDA<Integer> resultado = new Grafo<Integer>();
    resultado.InicializarGrafo();
    ConjuntoTDA<Integer> vertices = g.Vertices();
    int vertice = vertices.elegir();
    vertices.sacar(vertice);
    resultado.AgregarVertice(vertice);

    // Agregar todos los vértices al resultado
    while (!vertices.conjuntoVacio()) {
        int aux_vertice = vertices.elegir();
        vertices.sacar(aux_vertice);
        resultado.AgregarVertice(aux_vertice);
    }

    ConjuntoTDA<Integer> pendientes = g.Vertices();
    pendientes.sacar(vertice);
    ConjuntoTDA<Integer> visitados = new Conjunto<Integer>();
    visitados.inicializarConjunto();
    visitados.agregar(vertice);

    while (!pendientes.conjuntoVacio()) {
        int mejor_distancia = 0;
        int mejor_u = -1;
        int mejor_v = -1;
        boolean primero = true;

        // Búsqueda voraz de la arista de corte mínima entre visitados y pendientes
        ConjuntoTDA<Integer> aux_vis = clonar(visitados);
        while (!aux_vis.conjuntoVacio()) {
            int u = aux_vis.elegir();
            aux_vis.sacar(u);
            ConjuntoTDA<Integer> aux_pen = clonar(pendientes);
            while (!aux_pen.conjuntoVacio()) {
                int v = aux_pen.elegir();
                aux_pen.sacar(v);
                if (g.ExisteArista(u, v)) {
                    int p = g.PesoArista(u, v);
                    if (primero || p < mejor_distancia) {
                        mejor_distancia = p;
                        mejor_u = u;
                        mejor_v = v;
                        primero = false;
                    }
                }
            }
        }

        resultado.AgregarArista(mejor_u, mejor_v, mejor_distancia);
        resultado.AgregarArista(mejor_v, mejor_u, mejor_distancia); // no dirigido
        pendientes.sacar(mejor_v);
        visitados.agregar(mejor_v);
    }
    return resultado;
}

private static ConjuntoTDA<Integer> clonar(ConjuntoTDA<Integer> c) throws Exception {
    ConjuntoTDA<Integer> clon = new Conjunto<Integer>();
    clon.inicializarConjunto();
    ConjuntoTDA<Integer> aux = new Conjunto<Integer>();
    aux.inicializarConjunto();
    while (!c.conjuntoVacio()) {
        int elem = c.elegir();
        c.sacar(elem);
        aux.agregar(elem);
    }
    while (!aux.conjuntoVacio()) {
        int elem = aux.elegir();
        aux.sacar(elem);
        c.agregar(elem);
        clon.agregar(elem);
    }
    return clon;
}

public static GrafoTDA<Integer> kruskal(GrafoTDA<Integer> g) throws Exception {
    // Implementación sobre TDAs de cátedra con clase Par auxiliar
    GrafoTDA<Integer> resultado = new Grafo<Integer>();
    resultado.InicializarGrafo();
    ConjuntoTDA<Integer> vertices = g.Vertices();
    int cantidad = 0;
    while (!vertices.conjuntoVacio()) {
        int vertice = vertices.elegir();
        vertices.sacar(vertice);
        resultado.AgregarVertice(vertice);
        cantidad++;
    }

    // Cola de prioridad de aristas por peso
    ColaPrioridadTDA<Par> aristas = new ColaPrioridad<Par>();
    aristas.InicializarCola();
    VectorTDA<Par> conjuntos = new Vector<Par>();
    conjuntos.inicializarVector(cantidad);

    vertices = g.Vertices();
    int i = 0;
    while (!vertices.conjuntoVacio()) {
        int vertice = vertices.elegir();
        vertices.sacar(vertice);
        Par p = new Par();
        p.valor1 = vertice; // ID vértice
        p.valor2 = vertice; // ID conjunto inicial
        conjuntos.agregarElemento(i, p);
        i++;

        ConjuntoTDA<Integer> ady = g.Adyacentes(vertice);
        while (!ady.conjuntoVacio()) {
            int aux_vertice = ady.elegir();
            ady.sacar(aux_vertice);
            if (aux_vertice > vertice) { // Evitar aristas duplicadas en no dirigido
                Par arista = new Par();
                arista.valor1 = vertice;
                arista.valor2 = aux_vertice;
                aristas.AgregarElemento(arista, g.PesoArista(vertice, aux_vertice));
            }
        }
    }

    int cantidad_pendientes = cantidad;
    while (cantidad_pendientes > 1 && !aristas.ColaVacia()) {
        Par aux_par = aristas.RecuperarMinElemento();
        int c1 = -1, c2 = -1;
        for (i = 0; i < cantidad; i++) {
            if (conjuntos.recuperarElemento(i).valor1 == aux_par.valor1) {
                c1 = conjuntos.recuperarElemento(i).valor2;
            }
            if (conjuntos.recuperarElemento(i).valor1 == aux_par.valor2) {
                c2 = conjuntos.recuperarElemento(i).valor2;
            }
        }
        if (c1 != c2) {
            // Unificación de conjuntos
            for (i = 0; i < cantidad; i++) {
                if (conjuntos.recuperarElemento(i).valor2 == c2) {
                    conjuntos.recuperarElemento(i).valor2 = c1;
                }
            }
            resultado.AgregarArista(aux_par.valor1, aux_par.valor2, (int) aristas.RecuperarMinPrioridad());
            resultado.AgregarArista(aux_par.valor2, aux_par.valor1, (int) aristas.RecuperarMinPrioridad());
            cantidad_pendientes--;
        }
        aristas.EliminarMinPrioridad();
    }
    return resultado;
}

// Dispatcher ingenieril de MST basado en densidad de aristas
public static GrafoTDA<Integer> calcularMSTOptimo(GrafoTDA<Integer> g, int v, int e) throws Exception {
    // Umbral de densidad teórica
    double umbral = (double) (v * v) / (Math.log(v) / Math.log(2));
    if (e < umbral) {
        // Grafo ralo: Kruskal domina asintóticamente
        return kruskal(g);
    } else {
        // Grafo denso: Prim con matriz domina asintóticamente
        return prim(g);
    }
}

