import java.util.Arrays;

public class DijkstraShortestPath {
    public static int[] computeShortestDistances(int[][] adjacencyMatrix, int sourceNode) {
        int vertexCount = adjacencyMatrix.length;
        int[] distances = new int[vertexCount];
        boolean[] visited = new boolean[vertexCount];
        Arrays.fill(distances, Integer.MAX_VALUE);
        distances[sourceNode] = 0;

        for (int step = 0; step < vertexCount - 1; step++) {
            int closestVertex = selectUnvisitedMinimumVertex(distances, visited);
            if (closestVertex == -1) {
                break;
            }
            visited[closestVertex] = true;
            for (int neighbor = 0; neighbor < vertexCount; neighbor++) {
                int edgeWeight = adjacencyMatrix[closestVertex][neighbor];
                if (!visited[neighbor] && edgeWeight > 0 && distances[closestVertex] != Integer.MAX_VALUE) {
                    int candidateDistance = distances[closestVertex] + edgeWeight;
                    if (candidateDistance < distances[neighbor]) {
                        distances[neighbor] = candidateDistance;
                    }
                }
            }
        }
        return distances;
    }

    private static int selectUnvisitedMinimumVertex(int[] distances, boolean[] visited) {
        int minimumDistance = Integer.MAX_VALUE;
        int selectedVertex = -1;
        for (int vertex = 0; vertex < distances.length; vertex++) {
            if (!visited[vertex] && distances[vertex] < minimumDistance) {
                minimumDistance = distances[vertex];
                selectedVertex = vertex;
            }
        }
        return selectedVertex;
    }
}

