import heapq

def dijkstra_shortest_paths(adjacency_list: dict[int, list[tuple[int, int]]], source_node: int) -> dict[int, float]:
    distances: dict[int, float] = {node: float('inf') for node in adjacency_list}
    distances[source_node] = 0.0
    priority_queue: list[tuple[float, int]] = [(0.0, source_node)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)
        if current_distance > distances[current_node]:
            continue
        for neighbor, edge_weight in adjacency_list[current_node]:
            candidate_distance = current_distance + edge_weight
            if candidate_distance < distances[neighbor]:
                distances[neighbor] = candidate_distance
                heapq.heappush(priority_queue, (candidate_distance, neighbor))
    return distances

