public class PrimMinimumSpanningTree {
    public static int computeMstTotalWeight(int[][] costMatrix) {
        int vertexCount = costMatrix.length;
        boolean[] inTree = new boolean[vertexCount];
        int[] minEdgeWeight = new int[vertexCount];
        inTree[0] = true;
        for (int vertex = 1; vertex < vertexCount; vertex++) {
            minEdgeWeight[vertex] = costMatrix[0][vertex];
        }

        int totalMstWeight = 0;
        for (int step = 1; step < vertexCount; step++) {
            int bestVertex = -1;
            int smallestWeight = Integer.MAX_VALUE;
            for (int candidate = 1; candidate < vertexCount; candidate++) {
                if (!inTree[candidate] && minEdgeWeight[candidate] < smallestWeight) {
                    smallestWeight = minEdgeWeight[candidate];
                    bestVertex = candidate;
                }
            }
            inTree[bestVertex] = true;
            totalMstWeight += smallestWeight;
            for (int neighbor = 1; neighbor < vertexCount; neighbor++) {
                if (!inTree[neighbor] && costMatrix[bestVertex][neighbor] < minEdgeWeight[neighbor]) {
                    minEdgeWeight[neighbor] = costMatrix[bestVertex][neighbor];
                }
            }
        }
        return totalMstWeight;
    }
}

import java.util.Arrays;
import java.util.Comparator;

public class KruskalMinimumSpanningTree {
    public record Edge(int source, int target, int weight) {}

    public static int computeMstWeight(int vertexCount, Edge[] edges) {
        Arrays.sort(edges, Comparator.comparingInt(Edge::weight));
        int[] parent = new int[vertexCount];
        for (int i = 0; i < vertexCount; i++) {
            parent[i] = i;
        }
        int totalWeight = 0;
        int selectedEdges = 0;
        for (Edge edge : edges) {
            int rootSource = findRepresentative(parent, edge.source());
            int rootTarget = findRepresentative(parent, edge.target());
            if (rootSource != rootTarget) {
                parent[rootSource] = rootTarget;
                totalWeight += edge.weight();
                selectedEdges++;
                if (selectedEdges == vertexCount - 1) {
                    break;
                }
            }
        }
        return totalWeight;
    }

    private static int findRepresentative(int[] parent, int node) {
        if (parent[node] == node) {
            return node;
        }
        parent[node] = findRepresentative(parent, parent[node]);
        return parent[node];
    }
}

