def kruskal_mst_weight(vertex_count: int, edges: list[tuple[int, int, int]]) -> int:
    parent = list(range(vertex_count))

    def find_representative(node: int) -> int:
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    sorted_edges = sorted(edges, key=lambda edge: edge[2])
    total_weight = 0
    edges_added = 0

    for u_node, v_node, weight in sorted_edges:
        root_u = find_representative(u_node)
        root_v = find_representative(v_node)
        if root_u != root_v:
            parent[root_u] = root_v
            total_weight += weight
            edges_added += 1
            if edges_added == vertex_count - 1:
                break
    return total_weight
